#!/usr/bin/env node

import { execa } from "execa";
import { mkdtemp, rm, writeFile } from "fs/promises";
import { tmpdir } from "os";
import { join } from "path";
import yargs from "yargs";
import { hideBin } from "yargs/helpers";

import { buildDevCommand, buildDevConfig } from "./devCommand.js";
import {
  buildStructureCheckCommand,
  buildTypeCheckCommand,
  formatCommandFailure,
  withTypeCheckProject,
} from "./validateCommand.js";

await yargs(hideBin(process.argv))
  .scriptName("fastmcp")
  .command(
    "dev <file>",
    "Start a development server",
    (yargs) => {
      return yargs
        .positional("file", {
          demandOption: true,
          describe: "The path to the server file",
          type: "string",
        })

        .option("args", {
          describe:
            "JSON arguments passed to the tool (requires --tool), e.g. '{\"a\":1}'",
          type: "string",
        })

        .option("tool", {
          alias: "t",
          describe:
            "Call a tool non-interactively instead of launching the inspector",
          type: "string",
        })

        .option("watch", {
          alias: "w",
          default: false,
          describe: "Watch for file changes and restart server",
          type: "boolean",
        })

        .option("verbose", {
          alias: "v",
          default: false,
          describe: "Enable verbose logging",
          type: "boolean",
        });
    },

    async (argv) => {
      let configDir: string | undefined;

      try {
        if (argv.args !== undefined && !argv.tool) {
          console.error("[FastMCP Error] --args requires --tool");
          process.exitCode = 1;
          return;
        }

        if (argv.tool && argv.watch) {
          console.warn(
            "[FastMCP] --watch is ignored when calling a tool with --tool: the server runs for a single call.",
          );
        }

        let configPath: string | undefined;

        if (argv.tool) {
          configDir = await mkdtemp(join(tmpdir(), "fastmcp-dev-"));
          configPath = join(configDir, "mcp-cli.json");
          await writeFile(configPath, buildDevConfig(argv.file), "utf8");
        }

        const [command, ...commandArgs] = buildDevCommand({
          configPath,
          file: argv.file,
          tool: argv.tool,
          toolArgs: argv.args,
          watch: argv.watch,
        });

        if (argv.verbose) {
          console.log(
            `[FastMCP] Starting server: ${[command, ...commandArgs].join(" ")}`,
          );
          console.log(`[FastMCP] File: ${argv.file}`);
          console.log(
            `[FastMCP] Watch mode: ${argv.watch ? "enabled" : "disabled"}`,
          );

          if (argv.tool) {
            console.log(`[FastMCP] Tool: ${argv.tool}`);
          }
        }

        await execa(command, commandArgs, {
          stderr: "inherit",
          stdin: "inherit",
          stdout: "inherit",
        });
      } catch (error) {
        console.error(
          "[FastMCP Error] Failed to start development server:",
          error instanceof Error ? error.message : String(error),
        );

        if (argv.verbose && error instanceof Error && error.stack) {
          console.error("[FastMCP Debug] Stack trace:", error.stack);
        }

        // Not process.exit(): that would skip the `finally` block below and
        // leak the temporary config directory on every failed tool call.
        process.exitCode = 1;
      } finally {
        if (configDir) {
          await rm(configDir, { force: true, recursive: true });
        }
      }
    },
  )

  .command(
    "inspect <file>",
    "Inspect a server file",
    (yargs) => {
      return yargs.positional("file", {
        demandOption: true,
        describe: "The path to the server file",
        type: "string",
      });
    },

    async (argv) => {
      try {
        await execa({
          stderr: "inherit",
          stdout: "inherit",
        })`npx @modelcontextprotocol/inspector npx tsx ${argv.file}`;
      } catch (error) {
        console.error(
          "[FastMCP Error] Failed to inspect server:",
          error instanceof Error ? error.message : String(error),
        );

        process.exit(1);
      }
    },
  )

  .command(
    "validate <file>",
    "Validate a FastMCP server file for syntax and basic structure",
    (yargs) => {
      return yargs
        .positional("file", {
          demandOption: true,
          describe: "The path to the server file",
          type: "string",
        })

        .option("strict", {
          alias: "s",
          default: false,
          describe: "Enable strict validation (type checking)",
          type: "boolean",
        });
    },

    async (argv) => {
      try {
        const { existsSync } = await import("fs");
        const { resolve } = await import("path");
        const filePath = resolve(argv.file);

        if (!existsSync(filePath)) {
          console.error(`[FastMCP Error] File not found: ${filePath}`);
          process.exit(1);
        }

        console.log(`[FastMCP] Validating server file: ${filePath}`);

        try {
          await withTypeCheckProject(filePath, (project) => {
            const [typeCheckCommand, ...typeCheckArgs] = buildTypeCheckCommand(
              filePath,
              { project, strict: argv.strict },
            );

            return execa(typeCheckCommand, typeCheckArgs, {
              stderr: "pipe",
              stdout: "pipe",
            });
          });

          console.log("[FastMCP] ✓ TypeScript compilation successful");
        } catch (tsError) {
          console.error("[FastMCP] ✗ TypeScript compilation failed");

          const diagnostics = formatCommandFailure(tsError);

          if (diagnostics) {
            console.error(diagnostics);
          }

          process.exit(1);
        }

        const [structureCommand, ...structureArgs] =
          buildStructureCheckCommand(filePath);

        try {
          await execa(structureCommand, structureArgs, {
            stderr: "pipe",
            stdout: "pipe",
          });
        } catch (structureError) {
          // The child reports the reason on stderr, which execa captures. Without
          // replaying it the user only ever sees the generic hint below, even when
          // the server file has an error they could act on.
          const reason = formatCommandFailure(structureError);

          if (reason) {
            console.error(reason);
          } else {
            console.error("[FastMCP] ✗ Server structure validation failed");
            console.error(
              "Make sure the file properly imports and uses FastMCP",
            );
          }

          process.exit(1);
        }

        console.log(
          "[FastMCP] ✓ All validations passed! Server file looks good.",
        );
      } catch (error) {
        console.error(
          "[FastMCP Error] Validation failed:",
          error instanceof Error ? error.message : String(error),
        );

        process.exit(1);
      }
    },
  )

  .help()
  .parseAsync();
